(async () => {
  const result = [];
  const fonts = await figma.listAvailableFontsAsync();
  // Filter for Roboto and Lobster to see weights available
  const roboto = fonts.filter(f => f.fontName.family === "Roboto");
  const lobster = fonts.filter(f => f.fontName.family === "Lobster");

  result.push(`Roboto fonts found: ${roboto.length}`);
  roboto.forEach(f => result.push(`- Roboto ${f.fontName.style}`));

  result.push(`Lobster fonts found: ${lobster.length}`);
  lobster.forEach(f => result.push(`- Lobster ${f.fontName.style}`));

  return result.join("\n");
})()

