  };

(async () => {
  // Let's inspect the inside of 1:497 (Field) of Text Field to see what's in there.
  const fieldNode = await figma.getNodeByIdAsync("1:497");
  if (!fieldNode) return "Field not found";

  function getSubtree(node) {
    const info = { id: node.id, name: node.name, type: node.type };
    if ("children" in node) {
      info.children = node.children.map(getSubtree);
    }
    return info;
  }
  return getSubtree(fieldNode);
})()

