function textNodes(node, acc = []) {
  if (node.type === 'TEXT') {
    acc.push({
      id: node.id,
      name: node.name,
      characters: node.characters,
      fontSize: node.fontSize,
      fontName: node.fontName,
      fills: node.fills
    });
  } else if ('children' in node) {
    node.children.forEach(c => textNodes(c, acc));
  }
  return acc;
}

return textNodes(componentsPage);

