(async () => {
  // Let's get information about specific pages, starting with 00 · Start Here 设计任务 (0:1)
  const page = await figma.getNodeByIdAsync("0:1");
  const data = [];
  function traverse(node, depth = 0) {
    if (depth > 4) return;
    const item = { type: node.type, id: node.id, name: node.name };
    if (node.type === 'TEXT') {
      item.characters = node.characters;
    }
    data.push(item);
    if ('children' in node) {
      for (const child of node.children) {
        traverse(child, depth + 1);
      }
    }
  }
  traverse(page);
  return data.slice(0, 100);
})();

(async () => {
  const page0 = await figma.getNodeByIdAsync("0:1");

  function getFrameText(node) {
    let res = [];
    if (node.type === 'TEXT') {
      res.push(`${node.name}: ${node.characters}`);
    }
    if ('children' in node) {
      for (const child of node.children) {
        res = res.concat(getFrameText(child));
      }
    }
    return res;
  }

  // Get frame cards (5:13) and data cards (5:104)
  const frameCards = await figma.getNodeByIdAsync("5:13");
  const dataCards = await figma.getNodeByIdAsync("5:104");

  return {
    frameCards: getFrameText(frameCards),
    dataCards: getFrameText(dataCards)
  };
})();

