const page = await figma.getNodeAsync("5:2");
const frames = page.children.filter(n => n.type === "FRAME").map(f => f.name + " " + f.id);
let wires = 0;
const details = [];
for (const f of page.children.filter(n => n.type === "FRAME")) {
  let count = 0;
  const walk = (n) => { if (n.reactions && n.reactions.some(r => r.actions && r.actions.some(a => a.type === "NODE"))) count++; (n.children||[]).forEach(walk); };
  walk(f);
  wires += count;
