function brief(node, depth) {
  const out = { id: node.id, name: node.name, type: node.type, w: Math.round(node.width), h: Math.round(node.height) };
  if (node.type === 'TEXT') { out.chars = node.characters; try { out.fill = node.fills[0].color; } catch(e){} }
  if ('fills' in node && Array.isArray(node.fills) && node.fills.length && node.type !== 'TEXT') out.fillType = node.fills[0].type;
  if (depth > 0 && 'children' in node) out.children = node.children.map(c => brief(c, depth-1));
  return out;
}
