function summary(n, depth){
  depth = depth || 0;
  var o = {id:n.id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  if (n.type==='TEXT'){ o.chars = n.characters; try{o.fills=n.fills;}catch(e){} }
  if (n.type==='RECTANGLE'||n.type==='ELLIPSE'||n.type==='FRAME'||n.type==='VECTOR'){ try{o.fills=n.fills;}catch(e){} }
  if ('children' in n && depth<3){ o.children = n.children.map(function(c){return summary(c, depth+1);}); }
  return o;
}
