async function testReactions() {
  const f1 = figma.createFrame();
  const f2 = figma.createFrame();
  figma.currentPage.appendChild(f1);
  figma.currentPage.appendChild(f2);

  let res = "";
  try {
    f1.reactions = [{
      trigger: { type: 'ON_CLICK' },
      action: {
        type: 'NODE',
        destinationId: f2.id,
        navigation: 'NAVIGATE',
        transition: null
      }
    }];
    res = "Success! Standard format is accepted.";
  } catch (e) {
    res = e.toString();
  }

  f1.remove();
  f2.remove();
  return res;
}
return await testReactions();

