const out=[];
for (const id of ['0:1','1:2']) {
  const p = await figma.getNodeByIdAsync(id);
  await figma.setCurrentPageAsync(p);
  out.push('=== '+p.name);
  const texts = p.findAll(n=>n.type==='TEXT');
  texts.sort((a,b)=>a.absoluteTransform[1][2]-b.absoluteTransform[1][2] || a.absoluteTransform[0][2]-b.absoluteTransform[0][2]);
  for (const t of texts) out.push(t.characters);
  out.push('-- top children: '+p.children.map(c=>c.type+':'+c.name+':'+c.id+` ${Math.round(c.width)}x${Math.round(c.height)}`).join(' | '));
}
return out.join('\n');

const out=[];
for (const id of ['1:3','1:4','7:2']) {
  const p = await figma.getNodeByIdAsync(id);
  await figma.setCurrentPageAsync(p);
  out.push('=== '+p.name);
  const walk=(n,d)=>{ if(d>3) return; out.push(' '.repeat(d)+n.type+':'+n.name+':'+n.id+` ${Math.round(n.width)}x${Math.round(n.height)}`+(n.type==='COMPONENT_SET'?' props:'+JSON.stringify(n.componentPropertyDefinitions):'')); if('children' in n && n.type!=='COMPONENT' && n.type!=='INSTANCE') n.children.forEach(c=>walk(c,d+1)); };
  p.children.forEach(c=>walk(c,0));
}
return out.join('\n');

