(async () => {
  const workspacePage = figma.getNodeById("7:2");
  return workspacePage.children.map(c => {
    const list = [];
    const walk = (node) => {
      if (node.name.startsWith("Btn") || node.name.startsWith("Link") || node.name.startsWith("Tab") || node.name.includes("Claire")) {
        list.push({ id: node.id, name: node.name, type: node.type });
      }
      if ('children' in node) {
        for (const ch of node.children) walk(ch);
      }
    };
    walk(c);
    return { screen: c.name, matches: list };
  });
})()

