function check(f){
  const tb=f.findOne(n=>n.name.startsWith('TabBar'));
  const out={};
  for(const nm of ['Icon/Home','Icon/Dating','Avatar/Profile']){
    const node=tb.findOne(n=>n.name===nm);
    out[nm]=node&&node.reactions?node.reactions.length:null;
  }
  for(const lbl of ['Home','Dating','Profile']){
    const t=tb.findAll(n=>n.type==='TEXT'&&n.characters===lbl)[0];
    out['label/'+lbl]=t&&t.reactions?t.reactions.length:null;
  }
  return out;
}
return {explore:check(E),find:check(FP),profile:check(PR)};

