function desc(n){
  const o = {id:n.id, name:n.name, type:n.type, w:n.width, h:n.height, x:n.x, y:n.y};
  if (n.type==='TEXT') { o.chars = n.characters; o.font = n.fontName; o.size=n.fontSize; o.fills = JSON.stringify(n.fills); }
  else if ('fills' in n) { o.fills = JSON.stringify(n.fills); }
  if (n.type==='COMPONENT' || n.type==='COMPONENT_SET') o.key = n.key;
  const kids = n.children ? n.children.map(desc) : [];
  if (kids.length) o.children = kids;
  return o;
}
