const page = await figma.getNodeByIdAsync('8:2');
const comps = page.children.filter(n=>n.type==='COMPONENT').map(n=>({id:n.id, name:n.name}));
const screens = page.children.filter(n=>n.type==='FRAME' && n.width===375).map(n=>({id:n.id, name:n.name}));
const allReactions = [];
for (const s of page.children.filter(n=>n.type==='FRAME' && n.width===375)){
  const rs = s.findAll(x=>x.reactions && x.reactions.length>0).map(x=>({on:x.name, dest:x.reactions[0].actions[0].destinationId}));
  allReactions.push({screen:s.name, links:rs});
}
return {comps, screens, allReactions};

