const page = await figma.getNodeByIdAsync('8:2');
const summary = [];
for (const name of ['01_Get_Started','02_Home','03_Wallet','04_Add_Card','05_Payment','06_Receipt']){
  const s = page.findOne(n=>n.name===name);
  const links = s.findAll(x=>x.reactions && x.reactions.length>0).map(x=>({on:x.name, dest:x.reactions[0].actions[0].destinationId}));
  summary.push({screen:name, id:s.id, links});
}
return summary;

