(async () => {
  const pages = figma.root.children;
  const compPage = pages.find(p => p.name.includes("Components"));
  const mediaPage = pages.find(p => p.name.includes("Media"));

  const compInfo = compPage ? compPage.findAll(n => n.type === "COMPONENT").map(n => ({id: n.id, name: n.name})) : [];
  const mediaInfo = mediaPage ? mediaPage.findAll(n => n.type === "COMPONENT").map(n => ({id: n.id, name: n.name})) : [];

  return {
    components: compInfo,
    media: mediaInfo
  };
})()

(async () => {
  const node = figma.getNodeById("1:23");
  if (!node) return { error: "Button component not found" };

  function dumpNode(n) {
    const res = { id: n.id, name: n.name, type: n.type };
    if (n.children) {
      res.children = n.children.map(dumpNode);
    }
    return res;
  }

  return dumpNode(node);
})()

(async () => {
  const node = figma.getNodeById("1:26");
  if (!node) return { error: "Text Field component not found" };

  function dumpNode(n) {
    const res = { id: n.id, name: n.name, type: n.type };
    if (n.children) {
      res.children = n.children.map(dumpNode);
    }
    return res;
  }

  return dumpNode(node);
})()

