(async () => {
  const wsPage = figma.getNodeById("5:2");
  if (!wsPage) return { error: "Page 5:2 not found" };

  // Find top level children
  const nodes = wsPage.children;
  return {
    pageName: wsPage.name,
    childCount: nodes.length,
    children: nodes.map(n => ({ id: n.id, name: n.name, type: n.type }))
  };
})()

(async () => {
  const pages = figma.root.children;
  const pageDetails = [];
  for (const page of pages) {
    pageDetails.push({
      id: page.id,
      name: page.name,
      childCount: page.children.length,
      children: page.children.map(c => ({ id: c.id, name: c.name, type: c.type }))
    });
  }
  return pageDetails;
})()

(async () => {
  const wsPage = figma.getNodeById("5:2");
  if (!wsPage) return { error: "Workspace page not found" };
  await figma.setCurrentPageAsync(wsPage);

  // Create test rectangle
  const rect = figma.createRectangle();
  rect.resize(100, 100);
  wsPage.appendChild(rect);

  return {
    success: true,
    rectId: rect.id,
    wsChildrenCount: wsPage.children.length
  };
})()

(async () => {
  const wsPage = figma.getNodeById("5:2");
  if (!wsPage) return { error: "Page not found" };

  const children = wsPage.children;
  return {
    count: children.length,
    children: children.map(c => ({ id: c.id, name: c.name, type: c.type }))
  };
})()

