(async () => {
  const workspace = figma.getNodeById('7:2');
  for (const child of Array.from(workspace.children)) {
    child.remove();
  }

  const frameNames = ['01_Onboarding', '02_Home', '03_Explore', '04_Workout', '05_Analytics'];
  const created = {};
  for (let i = 0; i < frameNames.length; i++) {
    const f = figma.createFrame();
    f.name = frameNames[i];
    f.resize(390, 844);
    f.x = i * 440;
    f.y = 0;
    f.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
    workspace.appendChild(f);
    created[f.name] = f.id;
  }
  return JSON.stringify(created, null, 2);
})();

