function flat(node, depth=0){
  const o = { id: node.id, type: node.type, name: node.name, x: Math.round(node.x), y: Math.round(node.y), w: Math.round(node.width), h: Math.round(node.height) };
  if ('constraints' in node) o.constraints = node.constraints;
  if (node.type === 'TEXT') { o.characters = node.characters; o.fontSize = node.fontSize; o.fontName = node.fontName; }
  if ('children' in node && depth < 3) o.children = node.children.map(c => flat(c, depth+1));
  return o;
}
