const page = figma.root.children.find(p => p.id === "1:4");
const walk = (node) => {
  if (node.type === "COMPONENT") {
    return { id: node.id, name: node.name, type: node.type };
  }
  if ("children" in node) {
    return { id: node.id, name: node.name, type: node.type, children: node.children.map(walk) };
  }
  return { id: node.id, name: node.name, type: node.type };
};
return JSON.stringify(walk(page), null, 2);

