  out.push('=== '+p.name);
  const walk=(n,d)=>{
    if(d>4) return;
    let s='  '.repeat(d)+n.type+' '+n.id+' "'+n.name+'"';
    if('width' in n) s+=` ${Math.round(n.x)},${Math.round(n.y)} ${Math.round(n.width)}x${Math.round(n.height)}`;
    if(n.type==='TEXT') s+=' :: '+n.characters.slice(0,80);
    out.push(s);
    if('children' in n && n.type!=='INSTANCE' && !(n.type==='COMPONENT' && d>1)) n.children.forEach(c=>walk(c,d+1));
  };
  p.children.forEach(c=>walk(c,0));
}
