function dump(n, d){
  const o = {name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height),
    fills: ("fills" in n && Array.isArray(n.fills)) ? n.fills.map(f=>f.type) : null};
  if (d<3 && "children" in n) o.children = n.children.map(c=>dump(c,d+1));
  return o;
}
