(async () => {
  const pages = figma.root.children;
  const startHere = pages.find(p => p.name.includes("00"));
  if (!startHere) return "Start Here page not found";

  function extractText(node) {
    let result = [];
    if (node.type === "TEXT") {
      result.push({ name: node.name, text: node.characters });
    }
    if ("children" in node) {
      for (const child of node.children) {
        result = result.concat(extractText(child));
      }
    }
    return result;
  }

  return JSON.stringify(extractText(startHere), null, 2);
})();

(async () => {
  const pages = figma.root.children;
  const result = {};
  for (const page of pages) {
    result[page.name] = {
      id: page.id,
      childCount: page.children.length,
      children: page.children.map(c => ({ id: c.id, name: c.name, type: c.type }))
    };
  }
  return JSON.stringify(result, null, 2);
})();

(async () => {
  const page1 = figma.root.children.find(p => p.name.includes("Foundations"));
  const page2 = figma.root.children.find(p => p.name.includes("Components"));
  const page4 = figma.root.children.find(p => p.name.includes("Media"));

  function getSubtree(node) {
    if (!node) return null;
    return {
      id: node.id,
      name: node.name,
      type: node.type,
      children: "children" in node ? node.children.map(c => ({ id: c.id, name: c.name, type: c.type })) : []
    };
  }

  return JSON.stringify({
    Foundations: getSubtree(page1),
    Components: getSubtree(page2),
    Media: getSubtree(page4)
  }, null, 2);
})

