(async () => {
  const mediaPage = figma.root.children.find(p => p.name.includes("Media"));
  const mediaMap = {};

  function getMediaIds(node) {
    if (node.type === "COMPONENT") {
      mediaMap[node.name] = node.id;
    }
    if ("children" in node) {
      for (const child of node.children) {
        getMediaIds(child);
      }
    }
  }
  getMediaIds(mediaPage);
  return JSON.stringify(mediaMap, null, 2);
})();

