(async () => {
  const workspace = figma.root.children.find(p => p.name.includes("03"));
  await figma.setCurrentPageAsync(workspace);

  const frameNames = [
    "01_Home",
    "02_Shop",
    "03_Product",
    "04_Cart_Drawer",
    "05_Comparison",
    "06_Cart",
    "07_Checkout",
    "08_Contact",
    "09_Blog"
  ];

  const frames = {};
  frameNames.forEach((name, index) => {
    const f = workspace.children.find(c => c.name === name);
    if (f) {
      f.x = (index % 3) * 1600;
      f.y = Math.floor(index / 3) * 3600;
      frames[name] = f.id;
    }
  });

  return JSON.stringify(frames, null, 2);
})();

