async function deep(id,label){
  const n=await figma.getNodeByIdAsync(id);
  const rows=[];
  (function walk(x){
    const r=rOf(x);
    if(r.length) rows.push(x.name+":"+x.id+"="+JSON.stringify(r));
    (x.children||[]).forEach(walk);
  })(n);
  out[label]=rows;
}
