(async () => {
  await figma.loadFontAsync({ family: "Inter", style: "Regular" });
  await figma.loadFontAsync({ family: "Inter", style: "Medium" });
  await figma.loadFontAsync({ family: "Inter", style: "Semi Bold" });
  await figma.loadFontAsync({ family: "Inter", style: "Bold" });

  const pages = figma.root.children;
  let workspace = pages.find(p => p.name.includes("03 · Workspace"));
  if (!workspace) {
    workspace = figma.createPage();
    workspace.name = "03 · Workspace";
  }

  return { workspaceId: workspace.id, workspaceName: workspace.name };
})()

(async () => {
  const pages = figma.root.children;
  const workspace = pages.find(p => p.name.includes("03 · Workspace"));
  await figma.setCurrentPageAsync(workspace);

  const existingFrames = workspace.children.map(f => ({ id: f.id, name: f.name, type: f.type }));
  return { currentPage: figma.currentPage.name, existingFrames };
})()

(async () => {
  const pages = figma.root.children;
  const mediaPage = pages.find(p => p.name.includes("04 · Media"));
  if (!mediaPage) return "Media page not found";

  const nodes = mediaPage.findAll(n => n.type === "COMPONENT" || n.type === "COMPONENT_SET");
  const result = {};
  for (const n of nodes) {
    if (n.name.startsWith("Icon_") || n.name.startsWith("Logo_") || n.name.startsWith("Decor_")) {
      result[n.name] = { id: n.id, width: n.width, height: n.height };
    }
  }
  return result;
})()

