function describe(n, depth) {
  const d = { id: n.id, name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height) };
  if (n.type === 'TEXT') { try { d.chars = n.characters; d.font = n.fontName.family + '/' + n.fontName.style; d.size = n.fontSize; } catch(e){ d.err = String(e);} }
  if ('fills' in n) { try { d.fills = JSON.stringify(n.fills).slice(0, 300); } catch(e){ d.fillsErr = String(e);} }
  if ('children' in n && depth < 4) d.children = n.children.map(c => describe(c, depth+1));
  return d;
}
