(async () => {
  const page = await figma.getNodeByIdAsync("1:3");
  if (!page) return "Page 1:3 not found";

  // Find components, instances, and texts
  const nodes = page.children;
  let output = `Top-level nodes on page 1:3 (02 · Components):\n`;
  for (const child of nodes) {
