(async () => {
  // Check if figma.currentPage or any node supports reactions or if we need to use a different property
  // Typically, prototype interactions are configured on nodes via the 'reactions' property.
  // In the Figma Plugin API, reactions are read/write on SceneNode.
  // Let's print out what properties exist on a FrameNode or how to set reactions.
  const frame = figma.createFrame();
  const reactionKeys = Object.keys(frame).filter(k => k.toLowerCase().includes("reaction"));
  frame.remove();
  return { reactionKeys };
})();

(async () => {
  const frame = figma.createFrame();
  const reactions = frame.reactions;
  let protoKeys = [];
  for (let k in frame) {
    if (k.toLowerCase().includes("proto") || k.toLowerCase().includes("flow") || k.toLowerCase().includes("react")) {
      protoKeys.push(k);
    }
  }
  frame.remove();
  return { reactions, protoKeys };
})();

