function extractText(node) {
  let results = [];
  if (node.type === 'TEXT') {
    results.push({ id: node.id, name: node.name, text: node.characters });
  }
  if ('children' in node) {
    for (const child of node.children) {
      results.push(...extractText(child));
    }
  }
  return results;
}
return extractText(page);

