const page = await figma.getNodeByIdAsync('8:2');
await figma.setCurrentPageAsync(page);
for(const s of ["Regular","Medium","Bold"]) await figma.loadFontAsync({family:"DM Sans",style:s});
const names = ["01_Dashboard","02_Timeline","03_Task_Board","04_Files","05_Settings","06_Messages"];
const ids = {};
for(let i=0;i<6;i++){
  const f = figma.createFrame();
  page.appendChild(f);
  f.name = names[i];
  f.x = (i%2)*1560; f.y = Math.floor(i/2)*1144;
  f.resize(1440,1024);
  f.fills = [{type:'SOLID',color:{r:0.965,g:0.969,b:0.984}}];
  f.clipsContent = true;
  ids[names[i]] = f.id;
}
return JSON.stringify(ids);

