const out = {};
function dump(n, depth=0, maxDepth=3){
  const o = {id:n.id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  if (n.fills && n.fills.length) o.fills = n.fills.map(f=>f.type==='IMAGE'?{type:'IMAGE',imageHash:f.imageHash,scaleMode:f.scaleMode}:{type:f.type,color:f.color,opacity:f.opacity});
  if (n.type==='TEXT'){ o.chars=n.characters; o.font=n.fontName; o.size=n.fontSize; o.fills=n.fills; }
  if (n.children && depth<maxDepth) o.children = n.children.map(c=>dump(c, depth+1, maxDepth));
  return o;
}
