  const card = await figma.getNodeByIdAsync(id);
  const chipRect = card.children[card.children.length - 1]; // last = chip rect
  const statusText = card.children.find(c => c.type==='TEXT' && (c.characters==='Open Now' || c.characters==='Opens tomorrow'));
  if (chipRect && statusText) {
    card.insertChild(card.children.length - 1, statusText);
    reordered++;
  }
}
