// Recolor with strokes too. The previous detach attempt left detached groups whose vectors still have only strokes.
function recolorAll(node, color) {
  const targets = node.findAll(n => ['VECTOR','BOOLEAN_OPERATION','STAR','POLYGON','ELLIPSE','LINE','RECTANGLE'].includes(n.type));
  for (const t of targets) {
    try { t.fills = [{ type: 'SOLID', color }]; } catch (e) {}
    try { if (t.strokes && t.strokes.length > 0) t.strokes = [{ type: 'SOLID', color }]; } catch (e) {}
  }
}

