function svgIcon(svgPath, size) {
  const frame = figma.createNodeFromSvg(
    '<svg xmlns="[URL]" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + svgPath + '</svg>'
  );
  frame.resize(size, size);
  return frame;
}

