// add small group labels above library areas
function addLabel(text, x, y) {
  const t = figma.createText();
  t.fontName = {family:'Poppins', style:'Regular'};
  t.fontSize = 12;
  t.characters = text;
  t.letterSpacing = {unit:'PERCENT', value: 14};
  t.fills = [{type:'SOLID', color:{r:0.55,g:0.55,b:0.62}}];
  page.appendChild(t);
  t.x = x; t.y = y;
  return t.id;
}
